style.css:
@-moz-document domain("roblox.com") {
/* Change the top toolbar color */
    .rbx-header {
        background-color: #001736 !important;
        border-bottom: none !important;
    }

    /* Apply the background image to the absolute base layer */
    body {
        background-image: url("https://i.postimg.cc/SNHYvtcq/Persona-3-1024x576.jpg") !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center !important;
        background-color: #000 !important;
    }

    /* Force all common Roblox overlay layers to become invisible */
    #wrap, 
    main,
    .container-main, 
    .content,
    .bg-color,
    .dark-theme,
    .light-theme,
    [data-theme="dark"],
    [data-theme="light"],
    .game-home-page-container {
        background-color: transparent !important;
        background: transparent !important;
    }

    /* Optional: Make the left navigation menu slightly transparent */
    .left-col-list {
        background-color: rgba(0, 23, 54, 0.85) !important;
    }
}
